// Small typed DOM helpers shared by the page scripts.

/**
 * The element with this id, checked to be of the expected type. Throws if
 * it's missing or the wrong kind: a template/script mismatch should fail
 * loudly rather than as "cannot read properties of null" somewhere later.
 */
export function byId<T extends HTMLElement = HTMLElement>(id: string, type?: new () => T): T {
    const el = document.getElementById(id);
    if (!el) throw new Error(`#${id} not found`);
    if (type && !(el instanceof type)) throw new Error(`#${id} is not a ${type.name}`);
    return el as T;
}

/** Like byId, but returns null when the element is optional on this page. */
export function maybeId<T extends HTMLElement = HTMLElement>(id: string, type?: new () => T): T | null {
    const el = document.getElementById(id);
    if (!el || (type && !(el instanceof type))) return null;
    return el as T;
}

/** Create an element with properties and children in one go. */
export function el<K extends keyof HTMLElementTagNameMap>(
    tag: K,
    props: Partial<HTMLElementTagNameMap[K]> = {},
    ...children: (Node | string)[]
): HTMLElementTagNameMap[K] {
    const e = Object.assign(document.createElement(tag), props);
    e.append(...children);
    return e;
}

/**
 * A click on the backdrop (outside the box) closes a modal dialog. Only
 * clicks on the dialog itself count: a button pressed with Enter or Space
 * reports (0, 0), which is "outside" too.
 */
export function closeOnBackdropClick(dialog: HTMLDialogElement): void {
    dialog.addEventListener("click", (e) => {
        if (e.target !== dialog) return;
        const r = dialog.getBoundingClientRect();
        if (e.clientX < r.left || e.clientX > r.right || e.clientY < r.top || e.clientY > r.bottom) dialog.close();
    });
}

/** Whether a modal (a dialog, or the book popup) is open: the keyboard is its own until it closes. */
export function modalOpen(): boolean {
    return document.querySelector("dialog[open], .modal-overlay.open") !== null;
}

/** Message from an unknown thrown value. */
export function errorMessage(err: unknown): string {
    return err instanceof Error ? err.message : String(err);
}

/** fetch() JSON helper: throws with the server's text on non-2xx. */
export async function api<T = unknown>(method: string, url: string, body?: unknown, init: RequestInit = {}): Promise<T> {
    const res = await fetch(url, {
        method,
        credentials: "same-origin",
        headers: body === undefined ? {} : { "content-type": "application/json" },
        body: body === undefined ? null : JSON.stringify(body),
        ...init,
    });
    if (!res.ok) {
        const err = new Error((await res.text()).trim() || `HTTP ${res.status}`) as Error & { status?: number };
        err.status = res.status;
        throw err;
    }
    return (res.status === 204 ? null : await res.json()) as T;
}

/**
 * A status line (success/error message) for an element that starts hidden.
 * Returns say(text, isError).
 */
export function statusLine(id: string): (text: string, isError?: boolean) => void {
    const el = maybeId(id);
    return (text, isError = false) => {
        if (!el) return;
        el.hidden = false;
        el.textContent = text;
        el.className = isError ? "auth-error" : "auth-notice";
    };
}

/**
 * A URL the server made for this site, with the page's own scheme: behind an
 * HTTPS reverse proxy the server may only see plain HTTP and write http://.
 * Only a URL for this very host is changed.
 */
export function withPageScheme(url: string): string {
    const plain = `http://${location.host}`;
    if (location.protocol !== "https:" || !(url === plain || url.startsWith(plain + "/"))) return url;
    return "https://" + url.slice("http://".length);
}

/* ------------------------------------------------------------------ */
/* SVG icons, built without parsing markup (Trusted Types)             */
/* ------------------------------------------------------------------ */

const SVG_NS = "http://www.w3.org/2000/svg";

/** Attributes of an SVG element. */
export type SvgAttrs = Record<string, string | number>;

/** One shape of an icon: [tag, attributes], e.g. ["path", { d: "M6 6l12 12" }]. */
export type SvgShape = [tag: string, attrs: SvgAttrs];

/** An SVG element with these attributes and children. */
export function svgEl(tag: string, attrs: SvgAttrs = {}, ...children: Node[]): SVGElement {
    const e = document.createElementNS(SVG_NS, tag) as SVGElement;
    for (const [k, v] of Object.entries(attrs)) e.setAttribute(k, String(v));
    e.append(...children);
    return e;
}

/**
 * A 24×24 icon: <svg viewBox="0 0 24 24" aria-hidden="true" …attrs> with
 * these shapes. A string shape is a path's d. Built fresh each call, so it
 * can go straight into the page.
 */
export function icon(attrs: SvgAttrs, ...shapes: (SvgShape | string)[]): SVGSVGElement {
    return svgEl(
        "svg",
        { viewBox: "0 0 24 24", "aria-hidden": "true", ...attrs },
        ...shapes.map((s) => (typeof s === "string" ? svgEl("path", { d: s }) : svgEl(s[0], s[1]))),
    ) as SVGSVGElement;
}

/** The attributes of a stroked line icon, the usual kind. */
export function lineIcon(size: number, strokeWidth = 2): SvgAttrs {
    return {
        width: size,
        height: size,
        fill: "none",
        stroke: "currentColor",
        "stroke-width": strokeWidth,
        "stroke-linecap": "round",
        "stroke-linejoin": "round",
    };
}

/**
 * A URL from data that's safe in href or src: a path on this site (starting
 * with one "/"), a fragment, or http(s). Anything else (javascript:, data:,
 * "//host") gives "#".
 */
export function safeUrl(url: string | null | undefined): string {
    if (!url) return "#";
    if (url.startsWith("#")) return url;
    if (url.startsWith("/")) return url.startsWith("//") || url.startsWith("/\\") ? "#" : url;
    return /^https?:/i.test(url) ? url : "#";
}

/**
 * A random number in [0, 1) for shuffles and picks, which needn't be
 * unguessable. Ids use randomHex.
 */
export function random(): number {
    return Math.random();
}

/** `bytes` random bytes from crypto.getRandomValues, as hex: an id's random part. */
export function randomHex(bytes = 8): string {
    return Array.from(crypto.getRandomValues(new Uint8Array(bytes)), (b) => b.toString(16).padStart(2, "0")).join("");
}
